const raw = $input.first().json;
const b = raw.body || raw;
const action = b.action || '';
const uid = Number(b.wp_user_id) || 0;
const esc = s => String(s || '').replace(/'/g, "''");

if (!uid) return [{ json: { success: false, error: 'Missing wp_user_id' } }];

let query = '';

if (action === 'list_patterns') {
  const search = esc(b.search || '');
  const craft = esc(b.craft || '');
  const sort = b.sort || 'recent';
  const page = Math.max(1, Number(b.page) || 1);
  const per = Math.min(50, Math.max(1, Number(b.per_page) || 20));
  const offset = (page - 1) * per;
  const order = sort === 'oldest' ? 'created_at ASC' : (sort === 'title' ? 'title ASC' : 'created_at DESC');
  let extra = '';
  if (search) extra += ` AND (up.title ILIKE '%${search}%' OR up.pattern_summary_text ILIKE '%${search}%' OR up.detected_design_code ILIKE '%${search}%')`;
  if (craft) extra += ` AND up.craft_type = '${craft}'`;
  query = `SELECT up.*, COALESCE(cc.cnt,0) AS chat_count, COALESCE(rc.cnt,0) AS rewrite_count, COUNT(*) OVER() AS total_count FROM user_patterns up LEFT JOIN (SELECT pattern_id, COUNT(*) AS cnt FROM chat_sessions GROUP BY pattern_id) cc ON cc.pattern_id = up.id LEFT JOIN (SELECT pattern_id, COUNT(*) AS cnt FROM rewrite_sessions GROUP BY pattern_id) rc ON rc.pattern_id = up.id WHERE up.wp_user_id = ${uid} AND up.is_archived = FALSE${extra} ORDER BY ${order} LIMIT ${per} OFFSET ${offset}`;
  return [{ json: { action, uid, query, extra: { page, per } } }];
}

if (action === 'save_pattern') {
  const title = esc(b.title || b.detected_title || 'Untitled');
  const craft = esc(b.craft_type || b.detected_design_code || '');
  const fn = esc(b.original_filename || b.filename || '');
  const furl = esc(b.file_url || b.drive_link || '');
  const sh = esc(b.pattern_summary_html || '');
  const st = esc(b.pattern_summary_text || '');
  const ss = esc(JSON.stringify(b.pattern_summary_structured || b.structured_data || {}));
  const dc = esc(b.detected_design_code || '');
  const pid = esc(b.project_id || '');
  const fid = esc(b.file_id || '');
  const jid = esc(b.job_id || '');
  const md = esc(JSON.stringify(b.metadata || {}));
  const src = esc(b.source || 'upload');
  const parent = b.parent_pattern_id ? `'${esc(b.parent_pattern_id)}'` : 'NULL';
  if (pid) {
    query = `INSERT INTO user_patterns (wp_user_id,title,craft_type,original_filename,file_url,pattern_summary_html,pattern_summary_text,pattern_summary_structured,detected_design_code,project_id,file_id,job_id,metadata,source,parent_pattern_id) VALUES (${uid},'${title}','${craft}','${fn}','${furl}','${sh}','${st}','${ss}','${dc}','${pid}','${fid}','${jid}','${md}','${src}',${parent}) ON CONFLICT (project_id) DO UPDATE SET title=EXCLUDED.title, craft_type=EXCLUDED.craft_type, original_filename=EXCLUDED.original_filename, file_url=EXCLUDED.file_url, pattern_summary_html=EXCLUDED.pattern_summary_html, pattern_summary_text=EXCLUDED.pattern_summary_text, pattern_summary_structured=EXCLUDED.pattern_summary_structured, detected_design_code=EXCLUDED.detected_design_code, file_id=EXCLUDED.file_id, job_id=EXCLUDED.job_id, metadata=EXCLUDED.metadata, source=EXCLUDED.source, parent_pattern_id=EXCLUDED.parent_pattern_id, updated_at=NOW() RETURNING id`;
  } else {
    query = `INSERT INTO user_patterns (wp_user_id,title,craft_type,original_filename,file_url,pattern_summary_html,pattern_summary_text,pattern_summary_structured,detected_design_code,file_id,job_id,metadata,source,parent_pattern_id) VALUES (${uid},'${title}','${craft}','${fn}','${furl}','${sh}','${st}','${ss}','${dc}','${fid}','${jid}','${md}','${src}',${parent}) RETURNING id`;
  }
  return [{ json: { action, uid, query } }];
}

if (action === 'get_pattern') {
  const id = esc(b.id || '');
  query = `SELECT up.*, COALESCE(cc.cnt,0) AS chat_count, COALESCE(rc.cnt,0) AS rewrite_count FROM user_patterns up LEFT JOIN (SELECT pattern_id, COUNT(*) AS cnt FROM chat_sessions GROUP BY pattern_id) cc ON cc.pattern_id = up.id LEFT JOIN (SELECT pattern_id, COUNT(*) AS cnt FROM rewrite_sessions GROUP BY pattern_id) rc ON rc.pattern_id = up.id WHERE up.id = '${id}' AND up.wp_user_id = ${uid}`;
  return [{ json: { action, uid, query, pattern_id: id } }];
}

if (action === 'delete_pattern') {
  const id = esc(b.id || '');
  const hard = b.hard === 'true' || b.hard === true;
  query = hard ? `DELETE FROM user_patterns WHERE id='${id}' AND wp_user_id=${uid}` : `UPDATE user_patterns SET is_archived=TRUE, updated_at=NOW() WHERE id='${id}' AND wp_user_id=${uid}`;
  return [{ json: { action, uid, query, hard } }];
}

if (action === 'update_pattern') {
  const id = esc(b.id || '');
  const sets = [];
  if (b.title !== undefined) sets.push(`title='${esc(b.title)}'`);
  if (b.craft_type !== undefined) sets.push(`craft_type='${esc(b.craft_type)}'`);
  if (b.metadata !== undefined) sets.push(`metadata='${esc(JSON.stringify(b.metadata))}'`);
  if (b.is_archived !== undefined) sets.push(`is_archived=${b.is_archived ? 'TRUE' : 'FALSE'}`);
  if (!sets.length) return [{ json: { success: false, error: 'No fields to update' } }];
  query = `UPDATE user_patterns SET ${sets.join(', ')}, updated_at=NOW() WHERE id='${id}' AND wp_user_id=${uid}`;
  return [{ json: { action, uid, query } }];
}

return [{ json: { success: false, error: 'Unknown action: ' + action } }];

const rows = $input.all();
const all = rows.map(r => r.json);
const patterns = all.filter(p => p && p.id);
const first = patterns.length > 0 ? patterns[0] : null;
const total = first ? (Number(first.total_count) || 0) : 0;
return [{ json: { success: true, patterns, total, page: 1, pages: Math.max(1, Math.ceil(total / 20)) } }];
